function consultationForm(q) {
 const p = patient(q.patient), v = q.draft || {};
 return `<div class="mb-5 flex items-start justify-between gap-3"><div><span class="text-[10px] font-semibold uppercase tracking-widest text-teal-700">Consultation · ${q.number}</span><h2 class="mt-2 text-xl font-semibold text-slate-800">${esc(p.name)}</h2><p class="mt-1 text-xs text-slate-400">${p.id} · ${age(p.dob)} years · ${p.sex} · ${p.zone}</p></div>${badge(q.status, q.status === 'In consultation' ? 'teal' : 'gray')}</div>${p.allergies !== 'None' ? `<div class="mb-6 flex items-center gap-2 rounded-lg bg-amber-50 px-3 py-3 text-xs text-amber-800">${icon('warning')}Allergy: ${esc(p.allergies)}</div>` : ''}<form id="visit-form" data-id="${q.id}"><h3 class="mb-3 text-xs font-semibold text-slate-700">Vital signs</h3><div class="mb-6 grid grid-cols-2 gap-3 md:grid-cols-4">${field('BP (mmHg)', 'bp', v.bp || '', 'text', 'placeholder="120/80" pattern="[0-9]{2,3}/[0-9]{2,3}"')}${field('Temp. (°C)', 'temperature', v.temperature || '', 'number', 'placeholder="36.5" min="30" max="45" step="0.1"')}${field('Weight (kg)', 'weight', v.weight || '', 'number', 'placeholder="60" min="1" max="500" step="0.1"')}${field('Pulse (bpm)', 'pulse', v.pulse || '', 'number', 'placeholder="72" min="20" max="250"')}</div><div class="mb-4"><label for="complaint">Chief complaint</label><textarea id="complaint" name="complaint" rows="2" required placeholder="Reason for today's visit">${esc(v.complaint || '')}</textarea></div>${field('Diagnosis', 'diagnosis', v.diagnosis || '', 'text', 'required placeholder="Enter clinical diagnosis"')}<div class="mt-4"><label for="notes">Treatment notes</label><textarea name="notes" id="notes" rows="3" placeholder="Assessment, instructions, and follow-up care">${esc(v.notes || '')}</textarea></div><h3 class="mb-3 mt-6 text-xs font-semibold text-slate-700">Prescription</h3><div class="grid grid-cols-[1fr_90px] gap-3">${select('Medicine (optional)', 'medicine', [['','No medicine'], ...medicines.filter(m => expiryDays(m) >= 0 && m.stock > 0).map(m => [String(m.id), `${m.name} ${m.dose} (${m.stock} available)`])], v.medicine || '')}${field('Quantity', 'quantity', v.quantity || '', 'number', 'min="1" max="1000"')}</div><div class="mt-5">${field('Referral (optional)', 'referral', v.referral || '', 'text', 'placeholder="Facility and reason for referral"')}</div><p class="mt-3 text-[11px] text-slate-400">Completing a visit saves the consultation and dispenses the prescribed quantity.</p><div class="mt-6 flex flex-wrap justify-end gap-2 border-t border-slate-100 pt-5"><button type="submit" name="intent" value="save" class="btn btn-secondary" ${['Completed','Skipped'].includes(q.status) ? 'disabled' : ''}>Save visit</button><button type="button" data-action="skip" data-id="${q.id}" class="btn btn-secondary" ${['Completed','Skipped'].includes(q.status) ? 'disabled' : ''}>Skip patient</button><button type="submit" name="intent" value="complete" class="btn btn-primary" ${['Completed','Skipped'].includes(q.status) ? 'disabled' : ''}>${icon('check')}Complete visit</button></div></form>`;
}
function renderPatients(search = '', zone = 'All zones') {
 document.querySelector('#main').innerHTML = heading('Patient records', 'A complete picture of every patient in your community.', button('Register patient', 'register', 'plus', true)) + `<section class="card overflow-hidden"><div class="flex flex-wrap gap-3 p-5"><div class="relative min-w-[200px] flex-1"><span class="absolute left-3 top-2.5 text-slate-400">${icon('search')}</span><input id="patient-search" class="pl-10" placeholder="Search name, patient ID, or household…" aria-label="Search patient records" value="${esc(search)}"></div><select id="zone-filter" class="w-auto" aria-label="Filter by zone">${['All zones', 'Zone 1', 'Zone 2', 'Zone 3', 'Zone 4'].map(z => `<option ${zone === z ? 'selected' : ''}>${z}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Patient ID</th><th>Age / sex</th><th>Zone</th><th>Household</th><th></th></tr></thead><tbody id="patient-rows"></tbody></table></div><div class="border-t border-slate-100 px-5 py-3 text-[11px] text-slate-400" id="patient-count"></div></section><section id="patient-detail" class="mt-6"></section>`;
 filterPatients(); if(selectedPatient) renderPatientDetail();
}
function filterPatients() {
 const search = document.querySelector('#patient-search').value.trim().toLowerCase(), zone = document.querySelector('#zone-filter').value;
 const list = patients.filter(p => !p.archived && `${p.name} ${p.id} ${p.household}`.toLowerCase().includes(search) && (zone === 'All zones' || p.zone === zone));
 document.querySelector('#patient-rows').innerHTML = list.map(p => `<tr class="hover:bg-slate-50"><td><button data-action="patient-detail" data-id="${p.id}" class="flex items-center gap-3 text-left"><span class="flex h-9 w-9 items-center justify-center rounded-full bg-teal-50 text-[11px] font-semibold text-teal-700">${initials(p.name)}</span><span class="font-semibold text-slate-700">${esc(p.name)}</span></button></td><td class="text-slate-400">${p.id}</td><td>${age(p.dob)} / ${p.sex}</td><td>${p.zone}</td><td class="text-slate-400">${esc(p.household)}</td><td><button class="text-xs font-semibold text-teal-700" data-action="patient-detail" data-id="${p.id}">View record →</button></td></tr>`).join('') || '<tr><td colspan="6" class="empty">No matching patients. Try another name, ID, or zone.</td></tr>';
 document.querySelector('#patient-count').textContent = `${list.length} patient${list.length !== 1 ? 's' : ''} found`;
}
function renderPatientDetail() {
 const p = patient(selectedPatient); if(!p) return;
 const data = selectedTab === 'Profile' ? `<dl class="grid grid-cols-2 gap-x-8 gap-y-6 md:grid-cols-3">${[['Birthdate', p.dob], ['Sex', p.sex], ['Contact', p.contact || 'Not provided'], ['Zone', p.zone], ['Household', p.household || 'Not provided'], ['Allergies', p.allergies || 'None'], ['Address', p.address || 'Not provided'], ['Emergency contact', p.emergency || 'Not provided']].map(([k,v]) => `<div><dt class="text-[11px] text-slate-400">${k}</dt><dd class="mt-1.5 text-sm font-medium">${esc(v)}</dd></div>`).join('')}</dl>` : selectedTab === 'Visit history' ? (p.visits.map(v => `<article class="mb-3 rounded-lg border border-slate-200 p-4"><div class="flex justify-between"><h3 class="font-semibold">${esc(v.diagnosis)}</h3><span class="text-xs text-slate-400">${v.date}</span></div><p class="mt-2 text-sm">${esc(v.complaint)}</p><p class="mt-2 text-xs text-slate-400">BP: ${esc(v.bp || '—')} · Temperature: ${esc(v.temperature || '—')}°C · Weight: ${esc(v.weight || '—')} kg</p><p class="mt-2 text-sm">${esc(v.notes)}</p>${v.referral ? `<p class="mt-2 text-xs text-teal-700">Referral: ${esc(v.referral)}</p>` : ''}${v.medicine ? `<p class="mt-2 text-xs">Prescribed: ${esc(medicines.find(m => m.id === +v.medicine)?.name)} · ${v.quantity} units</p>` : ''}</article>`).join('') || '<div class="empty">No saved visits yet.</div>') : (p.immunizations?.map(v => `<div class="mb-2 flex justify-between rounded-lg bg-slate-50 p-4 text-sm"><span>${esc(v.vaccine)} · Dose ${v.dose}</span><span>${v.date}</span></div>`).join('') || '<div class="empty">No immunizations recorded.</div>') + `<div class="mt-3">${button('Record immunization', 'immunization', 'plus')}</div>`;
 document.querySelector('#patient-detail').innerHTML = `<div class="card"><div class="flex flex-wrap items-center justify-between gap-3 p-6"><div><h2 class="section-title">${esc(p.name)}</h2><p class="mt-1 text-xs text-slate-400">${p.id}</p></div><div class="flex flex-wrap gap-2 no-print">${button('Edit record', 'edit-patient', 'edit')}${button('Print', 'print', 'download')}${button('Archive', 'archive')}</div></div><div class="flex border-b border-slate-200 px-4">${['Profile', 'Visit history', 'Immunization'].map(t => `<button data-action="patient-tab" data-tab="${t}" class="tab ${selectedTab === t ? 'active' : ''}">${t}</button>`).join('')}</div><div class="p-6">${data}</div></div>`;
}
function renderInventory() {
 document.querySelector('#main').innerHTML = heading('Medicine inventory', 'The right medicine, in stock and ready for your patients.', button('Stock in medicine', 'stock', 'plus', true)) + `<div class="mb-6 grid grid-cols-3 gap-4">${[['Medicine types', medicines.length], ['Low-stock items', lowStock().length], ['Expiring in 60 days', medicines.filter(m => expiryDays(m) >= 0 && expiryDays(m) <= 60).length]].map(([l,v]) => `<div class="card p-5"><span class="text-xs text-slate-400">${l}</span><div class="mt-2 text-2xl font-semibold text-slate-800">${v}</div></div>`).join('')}</div><section class="card overflow-hidden"><div class="flex flex-wrap gap-3 p-5"><input id="medicine-search" placeholder="Search medicine or batch…" aria-label="Search medicines" class="flex-1"><select id="medicine-filter" class="w-auto" aria-label="Filter inventory"><option>All medicines</option><option>Low stock</option><option>Expiring soon</option><option>Expired</option></select></div><div class="table-wrap"><table><thead><tr><th>Medicine</th><th>Batch</th><th>Stock</th><th>Expiry date</th><th>Status</th><th></th></tr></thead><tbody id="medicine-rows"></tbody></table></div></section>`;
 filterMedicine();
}
function filterMedicine() {
 const search = document.querySelector('#medicine-search').value.toLowerCase(), filter = document.querySelector('#medicine-filter').value;
 const list = medicines.filter(m => `${m.name} ${m.batch}`.toLowerCase().includes(search) && (filter === 'All medicines' || (filter === 'Low stock' && m.stock < m.level) || (filter === 'Expiring soon' && expiryDays(m) <= 60 && expiryDays(m) >= 0) || (filter === 'Expired' && expiryDays(m) < 0)));
 document.querySelector('#medicine-rows').innerHTML = list.map(m => `<tr><td><div class="font-semibold text-slate-700">${m.name}</div><div class="mt-1 text-[11px] text-slate-400">${m.dose}</div></td><td class="text-slate-400">${m.batch}</td><td><span class="font-semibold ${m.stock < m.level ? 'text-rose-600' : 'text-slate-700'}">${m.stock}</span><span class="text-[11px] text-slate-400"> units</span></td><td>${m.expiry}</td><td>${badge(...medStatus(m))}</td><td><button class="text-xs font-semibold text-teal-700" data-action="dispense" data-id="${m.id}" ${m.stock === 0 || expiryDays(m) < 0 ? 'disabled' : ''}>Dispense</button></td></tr>`).join('') || '<tr><td colspan="6" class="empty">No medicines match your filters.</td></tr>';
}
function renderReports() {
 document.querySelector('#main').innerHTML = heading('Reports & analytics', 'Understand the activity behind your community’s care.') + `<section class="card mb-6 p-5"><form id="report-form" class="grid items-end gap-4 md:grid-cols-[1.4fr_1fr_1fr_auto]">${select('Report type', 'reportType', ['Consultation summary', 'Immunization summary', 'Inventory summary'], reportType)}${field('From', 'reportFrom', dateISO.slice(0,8) + '01', 'date', 'required')}${field('To', 'reportTo', dateISO, 'date', 'required')}<button class="btn btn-primary">${icon('reports')}Generate report</button></form></section><div class="mb-6 grid gap-6 md:grid-cols-2"><section class="card p-6"><h2 class="section-title">Weekly visits</h2><p class="mb-6 mt-1 text-[11px] text-slate-400">Sample data · current queue on the last day</p>${chart([34,46,39,52,41,27,queue.length], ['Wed','Thu','Fri','Sat','Sun','Mon','Today'])}</section><section class="card p-6"><h2 class="section-title">Common diagnoses</h2><p class="mb-6 mt-1 text-[11px] text-slate-400">Illustrative monthly distribution</p>${[['Hypertension', 38], ['Upper respiratory infection', 27], ['Diabetes', 20], ['Other consultations', 15]].map(([label,v]) => `<div class="mb-4"><div class="mb-2 flex justify-between text-xs"><span>${label}</span><span class="font-semibold">${v}%</span></div><div class="h-2 rounded-full bg-slate-100"><div class="h-2 rounded-full bg-teal-600" style="width:${v}%"></div></div></div>`).join('')}</section></div><section class="card overflow-hidden"><div class="p-5"><h2 class="section-title">Generated reports</h2><p class="mt-1 text-[11px] text-slate-400">Exports reflect the demo records available in this session.</p></div><div class="table-wrap"><table><thead><tr><th>Report</th><th>Period</th><th>Records</th><th>Export</th></tr></thead><tbody>${reportHistory.map((r,i) => `<tr><td class="font-medium">${esc(r.type)}</td><td class="text-xs text-slate-400">${r.from} — ${r.to}</td><td>${r.rows.length}</td><td><div class="flex gap-3"><button class="text-xs font-semibold text-teal-700" data-action="csv" data-id="${i}">CSV ↓</button><button class="text-xs font-semibold text-teal-700" data-action="pdf" data-id="${i}">Print / PDF</button></div></td></tr>`).join('') || '<tr><td colspan="4" class="empty">Choose a report type and date range, then generate your first report.</td></tr>'}</tbody></table></div></section>`;
}
